apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "video-analytics-demo.fullname" . }}
  labels:
{{ include "video-analytics-demo.labels" . | indent 4 }}
spec:
  replicas: {{ .Values.replicaCount }}
  selector:
    matchLabels:
      app.kubernetes.io/name: {{ include "video-analytics-demo.name" . }}
      app.kubernetes.io/instance: {{ .Release.Name }}
  template:
    metadata:
      labels:
        app.kubernetes.io/name: {{ include "video-analytics-demo.name" . }}
        app.kubernetes.io/instance: {{ .Release.Name }}
      annotations:
        rollme: {{ randAlphaNum 5 | quote }}
    spec:
    {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
    {{- end }}
      containers:
        - name: "{{ .Chart.Name }}-1"
          image: "{{ .Values.image.repository }}:{{ .Values.image.tag }}"
          command:
          - sh
          - -c
          {{- if .Values.ngcModel }}
          - apt update; 
            apt install wget unzip -y; 
            {{ .Values.ngcModel.getModel }}; 
            unzip *.zip; 
            cp -r {{ .Values.ngcModel.fileName }} {{ .Values.ngcModel.putModel }}; 
            sed -ie "s/..\/..\/models\/tlt_pretrained_models\/{{ .Values.ngcModel.name}}\/{{ .Values.ngcModel.fileName }}/\/opt\/nvidia\/deepstream\/deepstream-5.0\/samples\/configs\/tlt_pretrained_models\/{{ .Values.ngcModel.fileName }}/g" {{ .Values.ngcModel.modelConfig }}; 
            {{ .Values.command.apprunnercmd}} {{ .Values.command.apprunnername}} {{ .Values.command.appname}} {{ .Values.command.apparg}} >> /home/deepstream.log
          {{- else }}
          - {{ .Values.command.apprunnercmd}} {{ .Values.command.apprunnername}} {{ .Values.command.appname}} {{ .Values.command.apparg}}
          {{- end }}
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          resources:
            {{- toYaml .Values.resources | nindent 12 }}
          ports: 
            - name: http
              containerPort: 8554
              protocol: TCP
            - name: http1
              containerPort: {{ .Values.service.webuiPort }}
              protocol: TCP
          volumeMounts:
            - name: ipmount
              mountPath: /etc/config
            - name: create-config
              mountPath: /opt/nvidia/deepstream/create_config.py
              subPath: create_config.py
            - name: logs-mount
              mountPath: /home
        - name: "{{ .Chart.Name }}-azure"
          image: anguda/azure-iot:send-message
          env:
            - name: IOTHUB_DEVICE_CONNECTION_STRING
              value: {{ .Values.iotdeviceconnectionstring }}
          volumeMounts:
            - name: logs-mount
              mountPath: /home
      volumes:
        - name: ipmount
          configMap:
            name: {{ include "video-analytics-demo.fullname" . }}-configmap
        - name: logs-mount
          emptyDir: {}
        - name: create-config
          configMap:
            name: {{ include "video-analytics-demo.fullname" . }}-create-config
{{- with .Values.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
    {{- with .Values.affinity }}
      affinity:
        {{- toYaml . | nindent 8 }}
    {{- end }}
    {{- with .Values.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
    {{- end }}
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "video-analytics-demo.fullname" . }}-webui
  labels:
    name: {{ include "video-analytics-demo.fullname" . }}-webui      
{{ include "video-analytics-demo.labels" . | indent 4 }}
spec:
  replicas: {{ .Values.replicaCount }}
  selector:
    matchLabels:
      name: {{ include "video-analytics-demo.fullname" . }}-webui
      app.kubernetes.io/name: {{ include "video-analytics-demo.name" . }}
      app.kubernetes.io/instance: {{ .Release.Name }}
  template:
    metadata:
      labels:
        name: {{ include "video-analytics-demo.fullname" . }}-webui
        app.kubernetes.io/name: {{ include "video-analytics-demo.name" . }}
        app.kubernetes.io/instance: {{ .Release.Name }}
    spec:
      containers:
        - name: "{{ .Chart.Name }}-webui-1"
          image: {{ .Values.image.webui }}
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          env:
          - name: NODE_IP
            valueFrom:
              fieldRef:
                fieldPath: status.hostIP
          - name: DS_PORT
            value: "{{ .Values.service.nodePort }}"
          lifecycle:
            postStart:
              exec:
                command: ["/bin/sh", "-c", "sleep 45; bash /tmp/serverstart.sh; cp -r /tmp/play.html /usr/local/antmedia/webapps/WebRTCApp/play.html"]
          resources: {}
          volumeMounts:
          - mountPath: /tmp/play.html
            name: play
            subPath: play.html
          ports:
            - name: http
              containerPort: {{ .Values.service.webuiPort }}
              protocol: TCP
      volumes:
      - configMap:
          defaultMode: 420
          name: {{ include "video-analytics-demo.fullname" . }}-webui-configmap
        name: play

apiVersion: apps/v1
kind: Deployment
metadata:
  name: iotedged
  namespace: {{ include "edge-kubernetes.namespace" . | quote }}
  labels:
    app.kubernetes.io/name: {{ include "edge-kubernetes.name" . }}-iotedged
    helm.sh/chart: {{ include "edge-kubernetes.chart" . }}
    app.kubernetes.io/instance: {{ .Release.Name }}
    app.kubernetes.io/managed-by: {{ .Release.Service }}
spec:
  replicas: 1
  selector:
    matchLabels:
      app.kubernetes.io/name: {{ include "edge-kubernetes.name" . }}-iotedged
      app.kubernetes.io/instance: {{ .Release.Name }}
  template:
    metadata:
      labels:
        app.kubernetes.io/name: {{ include "edge-kubernetes.name" . }}-iotedged
        app.kubernetes.io/instance: {{ .Release.Name }}
    spec:
      containers:
        - name: iotedged
          image: "{{ .Values.iotedged.image.repository }}:{{ .Values.iotedged.image.tag }}"
          imagePullPolicy: {{ .Values.iotedged.image.pullPolicy }}
          command: ["/app/iotedged"]
          args: ["-c", "/etc/iotedged/config.yaml"]
          {{- if .Values.iotedged.data.resources }}
          resources:
{{ toYaml .Values.iotedged.data.resources | indent 12 }}
          {{- end }}
          env:
          - name: "IOTEDGE_LOG"
            value: "info"
          {{- if .Values.iotedged.data.httpsProxy }}
          - name: "https_proxy"
            value: {{ .Values.iotedged.data.httpsProxy | quote}}
          {{- end}}
          {{- if .Values.iotedged.data.noProxy }}
          - name: "no_proxy"
            value: {{ .Values.iotedged.data.noProxy | quote}}
          {{- end}}
          volumeMounts:
          - name: config
            mountPath: "/etc/iotedged"
            readOnly: true
          - name: edge-home
            mountPath: {{ .Values.iotedged.data.targetPath | quote }}
          {{- with .Values.iotedged.certificates }}
          {{- if .secret }}
          - name: edge-certs
            mountPath: "/etc/edgecerts"
            readOnly: true
          {{- end}}
          {{- end}}
          {{- if .Values.iotedged.data.useHostTrust }}
          - name: ca-edge-host-trust
            mountPath: "/etc/ssl/certs"
          {{- end }}
          {{- with .Values.provisioning.authentication }}
          {{- if .identitySecret }}
          - name: edge-authentication
            mountPath: "/etc/edge-authentication"
            readOnly: true
          {{- end}}
          {{- end}}
          {{- with .Values.provisioning.attestation }}
          {{- if .identitySecret }}
          - name: edge-attestation
            mountPath: "/etc/edge-attestation"
            readOnly: true
          {{- end}}
          {{- end}}
          ports:
            - name: management
              containerPort: {{ .Values.iotedged.ports.management }}
              protocol: TCP
            - name: workload
              containerPort: {{ .Values.iotedged.ports.workload }}
              protocol: TCP
          livenessProbe:
            httpGet:
              scheme: HTTPS
              path: "/systeminfo?api-version={{ .Values.iotedged.apiVersion }}"
              port: {{ .Values.iotedged.ports.management }}
          readinessProbe:
            httpGet:
              scheme: HTTPS
              path: "/systeminfo?api-version={{ .Values.iotedged.apiVersion }}"
              port: {{ .Values.iotedged.ports.management }}
      serviceAccount: "iotedged"
      {{- /* Render image pull secrets if they have been provided. */ -}}
      {{- if .Values.registryCredentials }}
      imagePullSecrets:
        - name: regcreds
      {{ end }}
      securityContext:
        runAsNonRoot: true
        runAsUser: 1000
      {{- if .Values.iotedged.fsGroup }}
        fsGroup: {{ .Values.iotedged.fsGroup }}
      {{ end }}
{{- if .Values.iotedged.nodeSelector }}
      nodeSelector:
{{ toYaml .Values.iotedged.nodeSelector | indent 8 }}
{{- end }}
      volumes:
      - name: config
        secret:
          secretName: iotedged-config
      {{- with .Values.provisioning.authentication }}
      {{- if .identitySecret }}
      {{- /*
      NOTE: This sets up iotedged with a volume "/etc/edge-authentication" populated with authentication certs.
    */}}
      - name: edge-authentication
        secret:
          secretName: {{ .identitySecret }}
          items:
          - key: {{ .identityCert | default "identity_certificate.pem" }}
            path: identity_cert
          - key: {{ .identityPk | default "identity_key.pem" }}
            path: identity_pk
      {{- end}}
      {{- end}}
      {{- with .Values.provisioning.attestation }}
      {{- if .identitySecret }}
      {{- /*
      NOTE: This sets up iotedged with a volume "/etc/edge-attestation" populated with the attestation certs.
    */}}
      - name: edge-attestation
        secret:
          secretName: {{ .identitySecret }}
          items:
          - key: {{ .identityCert | default "identity_certificate.pem" }}
            path: identity_cert
          - key: {{ .identityPk | default "identity_key.pem" }}
            path: identity_pk
      {{- end}}
      {{- end}}
      {{- if .Values.iotedged.data.useHostTrust }}
      - name: ca-edge-host-trust
        hostPath:
          path: /etc/ssl/certs
          type: Directory
      {{- end}}
      {{- with .Values.iotedged.certificates }}
      {{- if .secret }}
      {{- /*
        NOTE: This sets up iotedged with a volume "/etc/edgecerts" populated with the given CA certs.
      */}}
      - name: edge-certs
        secret:
          secretName: {{ .secret }}
          items:
          - key: {{ .device_ca_cert | default "device_ca_cert" }}
            path: device_ca_cert
          - key: {{ .device_ca_pk | default "device_ca_pk" }}
            path: device_ca_pk
          - key: {{ .trusted_ca_certs | default "trusted_ca_certs" }}
            path: trusted_ca_certs

      {{- end}}
      {{- else}}
      {{- /*
        NOTE: This sets up iotedged in the "quickstart" mode which is NOT meant
        for production use. For PoCs though, its wonderful! For production, this
        volume should probably be populated with proper CA certs.
      */}}
      {{- end}}
      - name: edge-home
        {{- if .Values.iotedged.data.persistentVolumeClaim }}
        persistentVolumeClaim:
          claimName: {{ .Values.iotedged.data.persistentVolumeClaim.name }}
          readOnly: false
        {{ else }}
        emptyDir: {}
        {{ end -}}

